#include <fcntl.h>
#include <unistd.h>
#define V 50257
#define N 1024
#define H 768
#define L 12
#define C 2304
#define M 3072
#define HEAD 12
#define HD 64
static float *W;
static void rd(off_t o, float *out, int n){ memcpy(out, W + o, n << 2); }
static void layernorm(float *x, float *g, float *b){
    float m = 0, v = 0;
    for (int i = 0; i < H; i++) m += x[i];
    m /= H;
    for (int i = 0; i < H; i++) { float d = x[i] - m; v += d * d; }
    v = 1.0f / sqrtf(v / H + 1e-5f);
    for (int i = 0; i < H; i++) x[i] = (x[i] - m) * v * g[i] + b[i];
