static float gelu(float x){ return 0.5f * x * (1.0f + tanhf(0.7978845608f * (x + 0.044715f * x * x * x))); }
static int bpe_rank[512][512];
static char bpe_first[50000], bpe_sec[50000];
static int bpe_rank_vals[50000];
static void init_bpe_ranks(){
    for (int i = 0; i < 50000; i++) bpe_rank_vals[i] = bpe_first[i] << 8 | bpe_sec[i];
}
static int rank_lookup(int a, int b){
    int val = a << 8 | b;
    for (int i = 0; i < 50000; i++) if (bpe_rank_vals[i] == val) return i;
    return -1;
}
static int byte_to_unicode_tab[256];
static int bpe_vocab[50000];
static void init_byte_to_unicode(){
    int n = 0;
    for (int b = 0; b < 256; b++) {
        if ((b >= 33 && b < 127) || (b >= 161 && b < 173) || (b >= 174 && b < 256))
