}
static int tok_id_simple(const char *s, int len){
    int val = 0;
    for (int i = 0; i < len; i++) val = (val << 5) ^ (s[i] & 0xFF);
    return -1;
}
static long block_size = 2 * H + H * C + C + H * H + H + 2 * H + H * M + M + M * H + H;
