static void add_output(const char *s, int len){
    memcpy(output_text + output_pos, s, len);
    output_pos += len;
}
static int bpe_tokenize_bytes(const unsigned char *bytes, int len){
    int symbols[1024];
    int ns = 0;
    for (int i = 0; i < len; i++) symbols[ns++] = byte_to_unicode_tab[bytes[i]];
    while (1) {
        int best = -1, best_rank = 50001, bi = -1;
        for (int i = 0; i < ns - 1; i++) {
            int r = rank_lookup(symbols[i], symbols[i + 1]);
            if (r >= 0 && r < best_rank) { best_rank = r; best = i; }
        }
        if (best < 0) break;
        symbols[best] = symbols[best] << 8 | symbols[best + 1];
        for (int j = best + 1; j < ns - 1; j++) symbols[j] = symbols[j + 1];
        ns--;
    }
    return ns;
}
int main(int argc, char **argv){
    if (argc < 4) { fprintf(stderr, "usage: %s ckpt bpe input\n", argv[0]); return 1; }
    init_byte_to_unicode();
    FILE *f = fopen(argv[2], "r");
    char line[4096];
    int nmerges = 0;
    fgets(line, sizeof(line), f);
    while (fgets(line, sizeof(line), f)) {
        char *sp = strchr(line, ' ');
        if (!sp) continue;
        *sp = 0;
        bpe_first[nmerges] = line[0];
        bpe_sec[nmerges] = sp[1];
        nmerges++;
        if (nmerges >= 50000) break;
    }
    fclose(f);
    init_bpe_ranks();
    int fd = open(argv[1], O_RDONLY);
    off_t fsize = lseek(fd, 0, SEEK_END);
    W = mmap(NULL, fsize, PROT_READ, MAP_PRIVATE, fd, 0);
    if (W == MAP_FAILED) { fprintf(stderr, "mmap failed\n"); return 1; }
    const char *input = argv[3];
    int len = strlen(input);
    unsigned char bytes[len + 1];
    memcpy(bytes, input, len);
    int ns = bpe_tokenize_bytes(bytes, len);
    return 0;
}
